function pixelNeighborhood(o,s){var r=o.record,at=Math.floor(r.height/2)*r.width+Math.floor(r.width/2),largest=-1;for(var i=0;i<o.pixels.length;i++){var xx=i%r.width,yy=Math.floor(i/r.width);if(xx<2||xx>=r.width-2||yy<2||yy>=r.height-2||o.baseline[i]===o.prediction[i])continue;var margin=Math.abs(o.scores[i]-s.threshold);if(margin>largest){largest=margin;at=i;}}var x=at%r.width,y=Math.floor(at/r.width),cells='';for(var dy=-2;dy<=2;dy++)for(var dx=-2;dx<=2;dx++){var v=o.pixels[(y+dy)*r.width+x+dx],gray=Math.round(255*v),cx=320+(dx+2)*42,cy=55+(dy+2)*42;cells+='<rect x="'+cx+'" y="'+cy+'" width="41" height="41" fill="rgb('+gray+','+gray+','+gray+')" stroke="'+(dx===0&&dy===0?'#b95739':'#d1b69a')+'" stroke-width="'+(dx===0&&dy===0?4:1)+'"/><text x="'+(cx+20)+'" y="'+(cy+25)+'" text-anchor="middle" style="fill:'+(v<.48?'#fffaf1':'#4c3829')+';font-size:12px">'+v.toFixed(2)+'</text>';}
return '<svg class="wl-neighborhood" viewBox="0 0 960 320" role="img" aria-label="当前图像的真实5乘5像素邻域、暗像素判断与FCN得分"><image href="'+assetBase+'images/'+r.id+'.png" x="10" y="35" width="260" height="208" style="filter:brightness('+s.exposure+')"/><rect x="'+(10+(x-2)*260/r.width)+'" y="'+(35+(y-2)*208/r.height)+'" width="'+(5*260/r.width)+'" height="'+(5*208/r.height)+'" fill="none" stroke="#b95739" stroke-width="3"/><text x="10" y="275">当前位置 x='+x+'，y='+y+'</text><path d="M280 140H309" stroke="#b95739" stroke-width="3"/>'+cells+'<text x="320" y="285">5×5灰度输入（0—1）</text><rect x="566" y="40" width="375" height="245" rx="8" fill="#f5e3ce" stroke="#d9b693"/><text x="586" y="77">中心灰度：'+o.pixels[at].toFixed(3)+'</text><text x="586" y="119">暗阈值 &lt; '+s.dark.toFixed(2)+' → '+(o.baseline[at]?'圈中':'不圈中')+'</text><text x="586" y="165">FCN得分：'+pct(o.scores[at])+'</text><text x="586" y="207">得分 ≥ '+s.threshold.toFixed(2)+' → '+(o.prediction[at]?'候选裂缝':'非候选')+'</text><text x="586" y="254" style="font-size:13px">'+(largest<0?'当前设置两种判断一致，显示图像中点。':'位置由当前真实差异选取，未用标签挑点。')+'</text></svg><p class="wl-fine">输入扰动与门槛变化会同步更新邻域、得分和判断。得分未经现场概率校准；03用完整像素标签对照全部结果。</p>';}
