function change(e){var el=e.target.closest('[data-wl-control]');if(!el)return;var k=el.dataset.wlControl,v=Number(el.value);if(!Number.isFinite(v))return;v=Math.max(Number(el.min)||0,Math.min(Number(el.max)||999,v));se.state[k]=v;refresh(c,se);}
